Abaixo está a solução completa e eficiente em Java para o problema.

### Abordagem

Duas retas não se intersectam no intervalo $[X_1, X_2]$ se e somente se uma delas estiver estritamente acima da outra em ambos os extremos $X_1$ e $X_2$. Em outras palavras, se calcularmos os valores $y_{i, 1} = A_i \cdot X_1 + B_i$ e $y_{i, 2} = A_i \cdot X_2 + B_i$ para cada reta $i$, duas retas $i$ e $j$ **não** se intersectam em $[X_1, X_2]$ se:
- $(y_{i, 1} < y_{j, 1} \text{ e } y_{i, 2} < y_{j, 2})$ ou $(y_{j, 1} < y_{i, 1} \text{ e } y_{j, 2} < y_{i, 2})$.

Assim, podemos contar o número total de pares de retas, $\binom{N}{2} = \frac{N(N - 1)}{2}$, e subtrair os pares que satisfazem essa condição (pares estritamente concordantes).

Para contar tais pares eficientemente em $O(N \log N)$:
1. Calculamos $(y_{i, 1}, y_{i, 2})$ para cada reta usando tipos `long` de 64 bits para evitar *overflow*.
2. Comprimimos as coordenadas de $y_{i, 2}$ para utilizá-las em uma Fenwick Tree (Binary Indexed Tree).
3. Ordenamos as retas crescentemente por $y_{i, 1}$.
4. Processamos as retas em grupos que possuem o mesmo valor de $y_{i, 1}$: para cada reta do grupo, consultamos na BIT quantos elementos já inseridos possuem $y_{k, 2} < y_{i, 2}$. Em seguida, inserimos todos os $y_{i, 2}$ do grupo atual na BIT.

```java
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {

    static class Line {
        long y1, y2;

        Line(long y1, long y2) {
            this.y1 = y1;
            this.y2 = y2;
        }
    }

    static class FenwickTree {
        int size;
        int[] tree;

        FenwickTree(int size) {
            this.size = size;
            this.tree = new int[size + 1];
        }

        void update(int index, int delta) {
            for (; index <= size; index += index & -index) {
                tree[index] += delta;
            }
        }

        int query(int index) {
            int sum = 0;
            for (; index > 0; index -= index & -index) {
                sum += tree[index];
            }
            return sum;
        }
    }

    public static void main(String[] args) throws IOException {
        FastReader in = new FastReader();

        int n = in.nextInt();
        long x1 = in.nextLong();
        long x2 = in.nextLong();

        Line[] lines = new Line[n];
        long[] y2Values = new long[n];

        for (int i = 0; i < n; i++) {
            long a = in.nextLong();
            long b = in.nextLong();
            long y1 = a * x1 + b;
            long y2 = a * x2 + b;
            lines[i] = new Line(y1, y2);
            y2Values[i] = y2;
        }

        // Compressão de coordenadas para y2
        Arrays.sort(y2Values);
        int uniqueCount = 0;
        for (int i = 0; i < n; i++) {
            if (i == 0 || y2Values[i] != y2Values[i - 1]) {
                y2Values[uniqueCount++] = y2Values[i];
            }
        }

        // Ordenar as retas por y1 crescente
        Arrays.sort(lines, (l1, l2) -> Long.compare(l1.y1, l2.y1));

        FenwickTree bit = new FenwickTree(uniqueCount);
        long concordantPairs = 0;

        int i = 0;
        while (i < n) {
            int j = i;
            // Agrupar retas com o mesmo y1
            while (j < n && lines[j].y1 == lines[i].y1) {
                j++;
            }

            // Consultar para cada elemento do grupo
            for (int k = i; k < j; k++) {
                int rank = binarySearch(y2Values, uniqueCount, lines[k].y2) + 1;
                concordantPairs += bit.query(rank - 1);
            }

            // Inserir os elementos do grupo na BIT
            for (int k = i; k < j; k++) {
                int rank = binarySearch(y2Values, uniqueCount, lines[k].y2) + 1;
                bit.update(rank, 1);
            }

            i = j;
        }

        long totalPairs = (long) n * (n - 1) / 2;
        long intersectingPairs = totalPairs - concordantPairs;

        System.out.println(intersectingPairs);
    }

    private static int binarySearch(long[] arr, int len, long val) {
        int low = 0, high = len - 1;
        while (low <= high) {
            int mid = (low + high) >>> 1;
            if (arr[mid] == val) {
                return mid;
            } else if (arr[mid] < val) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return -1;
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}
